import React, { useEffect, useState } from "react";
import RemoveIcon from "@mui/icons-material/Remove";
import AddIcon from "@mui/icons-material/Add";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";

export default function FAQ() {
  const dispatch = useDispatch();
  const [faqList, setFaqList] = useState([]);
  const [formData, setFormData] = useState({
    heading: "",
    question: "",
    answer: "",
  });

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.faqs)
      .then(async (res) => {
        let faqData = [];
        let data = res?.data?.faqs;
        let keys = Object.keys(data);
        for (let i = 0; i < keys.length; i++) {
          let subData = { heading: keys[i], data: [] };
          for (let j = 0; j < data[keys[i]].length; j++) {
            let ques_ans = {
              question: data[keys[i]][j]["question"],
              answer: data[keys[i]][j]["answer"],
              id: data[keys[i]][j]["id"],
              button: 0,
            };
            subData["data"].push(ques_ans);
          }
          faqData.push(subData);
        }
        setFaqList(faqData);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const openFaqContent = (e, index, index1) => {
    let data = [...faqList];
    data[index]["data"][index1]["button"] =
      data[index]["data"][index1]["button"] == 0 ? 1 : 0;
    setFaqList(data);
    e.currentTarget.nextElementSibling.classList.toggle("active");
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.faqs}/${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const uploadData = async (e) => {
    await http
      .post(apisPath?.admin?.faqs, formData)
      .then((res) => {
        // console.log(res);
        setFormData({
          heading: "",
          question: "",
          answer: "",
        });
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const handleInputChange = (e) => {
    const { name, value } = e?.target;

    setFormData((prev) => {
      return { ...prev, [name]: value };
    });
  };

  // const deleteItem = (parentIndex, childIndex) => {
  //   setFaqList((prevState) => {
  //     var updatedState = [...prevState];
  //     updatedState[parentIndex].data = updatedState[parentIndex]?.data.filter(
  //       (_, i) => {
  //         return i !== childIndex;
  //       }
  //     );

  //     return updatedState;
  //   });
  // };

  return (
    <div className="faq">
      <h3 className="faq__heading page_heading">FAQ's</h3>
      <div className="faq__content">
        <div className="faq__content__form">
          <div className="faq__content__form__heading">
            <label htmlFor="heading">Heading</label>
            <input
              type="text"
              id="heading"
              name="heading"
              placeholder="Enter here"
              value={formData?.heading}
              onChange={handleInputChange}
            />
          </div>
          <div className="faq__content__form__question">
            <label htmlFor="question">Question</label>
            <input
              type="text"
              id="question"
              name="question"
              placeholder="Enter here"
              value={formData?.question}
              onChange={handleInputChange}
            />
          </div>
          <div className="faq__content__form__answer">
            <label htmlFor="answer">Answer</label>
            <input
              type="text"
              id="answer"
              name="answer"
              placeholder="Enter here"
              value={formData?.answer}
              onChange={handleInputChange}
            />
          </div>
          <button className="button-red" onClick={uploadData}>
            Add to FAQ's
          </button>
        </div>

        <div className="faq__content__faq_list">
          <h4 className="faq__content__faq_list__subHeading page_subheading">
            FAQ list
          </h4>
          <div className="faq__content__faq_list__content">
            {faqList?.length > 0 ? (
              faqList?.map((faq, index) => {
                return (
                  <div
                    className="faq__content__faq_list__content__faq"
                    key={index}
                  >
                    <label>{faq?.heading}</label>
                    <div className="faq__content__faq_list__content__faq__content">
                      {faq?.data?.map((item, itemIndex) => {
                        return (
                          <div
                            className="faq__content__faq_list__content__faq__content__card"
                            key={itemIndex}
                          >
                            <div className="faq__content__faq_list__content__faq__content__card__content">
                              <span
                                className="faq__content__faq_list__content__faq__content__card__content__question"
                                onClick={(e) =>
                                  openFaqContent(e, index, itemIndex)
                                }
                              >
                                {item?.question}{" "}
                                {item?.button === 0 ? (
                                  <AddIcon />
                                ) : (
                                  <RemoveIcon />
                                )}
                              </span>
                              <span className="faq__content__faq_list__content__faq__content__card__content__answer">
                                {item?.answer}
                              </span>
                            </div>
                            <button
                              className="button-red"
                              onClick={() => deleteData(item?.id)}
                            >
                              Delete
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })
            ) : (
              <div className="no_data_found">No Data Found</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
